 document.addEventListener('click',function(e){const el=e.target.closest('[data-j7-act]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const a=el.dataset.j7Act,id=el.dataset.id;if(a==='apply')apply(id);if(a==='close')closeLayer();if(a==='compare')openCompare();if(a==='directory')openDirectory(id);if(a==='enter')enter(id);if(a==='scene'){state.scene=id;renderCompare()}if(a==='choose'){state.choice=id||state.theme;remember();updateSwitches();if(state.layer==='compare')renderCompare();toast('已记下你喜欢的方案：'+design(state.choice).name+'。')}if(a==='draw'){const other=designs.filter(x=>x.id!==state.theme);apply(other[Math.floor(Math.random()*other.length)].id)}if(a==='voice'){closeLayer();J5.state().terminal=true;navigate('chat')}},true);
 document.addEventListener('keydown',function(e){if(e.altKey&&/^[1-9]$/.test(e.key)&&Number(e.key)>0&&Number(e.key)<=designs.length){e.preventDefault();apply(designs[Number(e.key)-1].id)}if(!state.layer)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeLayer()}if(e.key==='Tab'){const items=[...rootLayer().querySelectorAll('button:not(:disabled),input,a[href]')].filter(x=>x.offsetParent!==null),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}},true);
 window.J7={designs,state,apply,enter,openCompare,openDirectory,closeLayer,design,requestInfo,updateMind,home};window.J6={closeLayer};
 J5.init();S.settings.supervise=false;palette();const view=hash.get('view')||'chat';U.route=view==='voice'?'chat':view;if(!admin()&&!J5.publicRoutes.has(U.route))U.route='chat';if(J5.isPublic()&&!['chat','screen'].includes(U.route))U.route='chat';J5.state().terminal=U.route==='chat';if(U.route==='screen')J5.state().board=admin()&&!J5.isPublic()?'all':'family';render();
 if(hash.get('demo')==='effects')setTimeout(()=>{if(U.route==='chat'&&U.vm5?.phase==='ready'&&!J7Effects.state.active)J7Effects.start()},900);
